import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Interface: DatapackModule","description":"","frontmatter":{},"headers":[],"relativePath":"api/twine/interfaces/DatapackModule.md","filePath":"api/twine/interfaces/DatapackModule.md"}'),c={name:"api/twine/interfaces/DatapackModule.md"};function d(n,e,i,s,l,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<p><a href="./../">twine</a> / DatapackModule</p><h1 id="interface-datapackmodule" tabindex="-1">Interface: DatapackModule <a class="header-anchor" href="#interface-datapackmodule" aria-label="Permalink to &quot;Interface: DatapackModule&quot;">​</a></h1><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/e18dd00553ede49790ed5aba7e4de326ac000085/twine/src/module.interface.ts#L14" target="_blank" rel="noreferrer">module.interface.ts:14</a></p><p>A datapack module is a class with an optional constructor and the lifecycle hooks below. It is instantiated once by <a href="./../classes/DatapackFactory.html">DatapackFactory</a> when its containing module tree is enabled (i.e. it is reachable through the root module&#39;s <code>imports</code>). A module NOT reachable through <code>imports</code> is never constructed and emits nothing - that is the compile-time disable.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="onactivate" tabindex="-1">onActivate()? <a class="header-anchor" href="#onactivate" aria-label="Permalink to &quot;onActivate()?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>onActivate</strong>(<code>ctx</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/e18dd00553ede49790ed5aba7e4de326ac000085/twine/src/module.interface.ts#L41" target="_blank" rel="noreferrer">module.interface.ts:41</a></p><p>Runs once when this module&#39;s <code>area</code> becomes active (see <a href="./ModuleMetadata.html#area">ModuleMetadata.area</a>) - e.g. summon a level&#39;s entities. Only meaningful on an <code>area</code> module; emitted into its generated <code>&lt;name&gt;/activate</code> function.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="ctx" tabindex="-1">ctx <a class="header-anchor" href="#ctx" aria-label="Permalink to &quot;ctx&quot;">​</a></h5><p><code>FunctionContext</code></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><hr><h3 id="ondeactivate" tabindex="-1">onDeactivate()? <a class="header-anchor" href="#ondeactivate" aria-label="Permalink to &quot;onDeactivate()?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>onDeactivate</strong>(<code>ctx</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/e18dd00553ede49790ed5aba7e4de326ac000085/twine/src/module.interface.ts#L47" target="_blank" rel="noreferrer">module.interface.ts:47</a></p><p>Runs once when this module&#39;s <code>area</code> becomes inactive - e.g. despawn the level&#39;s entities and clean up. Emitted into <code>&lt;name&gt;/deactivate</code>.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="ctx-1" tabindex="-1">ctx <a class="header-anchor" href="#ctx-1" aria-label="Permalink to &quot;ctx&quot;">​</a></h5><p><code>FunctionContext</code></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><hr><h3 id="onload" tabindex="-1">onLoad()? <a class="header-anchor" href="#onload" aria-label="Permalink to &quot;onLoad()?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>onLoad</strong>(<code>ctx</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/e18dd00553ede49790ed5aba7e4de326ac000085/twine/src/module.interface.ts#L25" target="_blank" rel="noreferrer">module.interface.ts:25</a></p><p>Appended to the shared <code>load</code> function (runs on pack load / <code>/reload</code>). Always runs - load-time setup is not gated by the runtime flag.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="ctx-2" tabindex="-1">ctx <a class="header-anchor" href="#ctx-2" aria-label="Permalink to &quot;ctx&quot;">​</a></h5><p><code>FunctionContext</code></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><hr><h3 id="ontick" tabindex="-1">onTick()? <a class="header-anchor" href="#ontick" aria-label="Permalink to &quot;onTick()?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>onTick</strong>(<code>ctx</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/e18dd00553ede49790ed5aba7e4de326ac000085/twine/src/module.interface.ts#L34" target="_blank" rel="noreferrer">module.interface.ts:34</a></p><p>Appended to the shared <code>tick</code> function (runs every game tick) - but only reached while every <code>area</code> ancestor of this module is active. Put per-tick work here (proximity checks, timers); it costs nothing while an ancestor area is inactive, because the parent&#39;s single <code>active</code> check skips the whole subtree before this is ever called.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="ctx-3" tabindex="-1">ctx <a class="header-anchor" href="#ctx-3" aria-label="Permalink to &quot;ctx&quot;">​</a></h5><p><code>FunctionContext</code></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><hr><h3 id="register" tabindex="-1">register()? <a class="header-anchor" href="#register" aria-label="Permalink to &quot;register()?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>register</strong>(<code>dp</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/e18dd00553ede49790ed5aba7e4de326ac000085/twine/src/module.interface.ts#L19" target="_blank" rel="noreferrer">module.interface.ts:19</a></p><p>Arbitrary one-off setup: declare extra objectives, create standalone functions, register structures, etc. Runs once at build time.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="dp" tabindex="-1">dp <a class="header-anchor" href="#dp" aria-label="Permalink to &quot;dp&quot;">​</a></h5><p><code>Datapack</code></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p>',54)])])}const m=a(c,[["render",d]]);export{p as __pageData,m as default};
